'use strict';
// Presentation adapter. Only input intent leaves the browser; the server owns PVP state.
const TZNet={
 socket:null,id:null,token:null,code:null,state:null,active:false,menu:false,intentional:false,seq:0,round:0,rtt:0,lastPacket:0,retryAt:0,retries:0,containers:[],remote:new Map(),target:null,priorAmmo:null,available:false,setupMap:'sector07',
 send(data){if(this.socket?.readyState===1&&this.socket.bufferedAmount<65536)this.socket.send(JSON.stringify(data))},
 command(type){if(this.active&&this.state?.status==='playing'&&!this.menu)this.send({type})},
 localOnly(){return /^(localhost\.?|127\.[\d.]+|\[::1\])$/i.test(new URL(location.href).hostname)},
 inviteHint(){const local=this.localOnly(),port=new URL(location.href).port||'80';$('netInviteHint').textContent=local?`当前是仅本机可用的地址。和朋友联机时，请双方用房主电脑的局域网 IP:${port} 打开游戏，再创建或加入房间。`:'朋友可通过同一游戏网址和邀请链接加入；自建房主需保持游戏服务运行。';return local},
 async open(){showScreen('network');$('netSetup').hidden=false;$('netLobby').hidden=true;$('netStatus').textContent='正在检查联机服务…';$('netCreate').disabled=$('netJoin').disabled=true;
  this.inviteHint();try{const response=await fetch('/api/config',{cache:'no-store',signal:AbortSignal.timeout(4000)});const config=await response.json();if(!response.ok||config.multiplayer!==true)throw Error();if(config.mapRevision!==TZWorld.CONFIG.mapRevision){this.available=false;$('netStatus').textContent='地图版本已更新，请从新版游戏服务地址进入，或重启房主的游戏服务。';return}this.available=true;$('netStatus').textContent='服务器已连接 · 创建房间后，把邀请链接或房间码发给朋友';$('netCreate').disabled=$('netJoin').disabled=false}catch{this.available=false;$('netStatus').textContent='此页面尚未启用联机服务。请从已启动的联机服务器网址打开游戏；单机仍可游玩。'}
 },
 connect(type){if(!this.available)return;this.intentional=false;this.retries=0;$('netStatus').textContent='正在连接房间…';$('netCreate').disabled=$('netJoin').disabled=true;this.connectSocket({type,name:$('netName').value.trim()||'干员',code:$('netCode').value.trim(),mapId:$('netMap').value,mode:$('netMode').value||'ffa',classId:ClassUI.selected,settings:RoomUI.read()})},
 connectSocket(first){const ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/ws');this.socket=ws;const timeout=setTimeout(()=>{if(ws.readyState!==1)ws.close()},6000);
  ws.addEventListener('open',()=>{clearTimeout(timeout);this.lastPacket=performance.now();this.send(first)});
  ws.addEventListener('message',event=>{let data;try{data=JSON.parse(event.data)}catch{return}this.lastPacket=performance.now();
   if(data.type==='welcome'){this.id=data.id;this.code=data.code;this.token=data.token;this.retries=0;$('netStatus').textContent='连接成功';try{sessionStorage.setItem('tactical-room',JSON.stringify({code:this.code,token:this.token}))}catch(_){}return}
   if(data.type==='state'){this.receive(data);return}
   if(data.type==='pong'){this.rtt=Math.round(performance.now()-data.at);return}
   if(data.type==='error'){$('netStatus').textContent=data.message;$('netCreate').disabled=$('netJoin').disabled=false;if(first.type==='resume'){this.leave();showScreen('network');$('netSetup').hidden=false;$('netLobby').hidden=true;$('netStatus').textContent=data.message+'，请重新加入房间。'}else if(!this.id){this.intentional=true;ws.close()}return}
  });
  ws.addEventListener('close',()=>{clearTimeout(timeout);if(this.socket!==ws||this.intentional)return;clearInput();$('netStatus').textContent=this.code?'连接中断，正在尝试重连…':'无法连接服务器，请重试';$('netCreate').disabled=$('netJoin').disabled=false;if(this.token&&this.retries<8){this.retryAt=performance.now()+1000;this.retries++;setTimeout(()=>{if(!this.intentional&&this.socket===ws)this.connectSocket({type:'resume',code:this.code,token:this.token})},1000)}else{$('netStatus').textContent='连接已断开，请退出后重新加入房间';$('netBanner').textContent='连接已断开 · 请返回大厅';this.active=false;paused=true}});
  ws.addEventListener('error',()=>{});
 },
 receive(s){if(s.mapRevision!==TZWorld.CONFIG.mapRevision){this.leave();showScreen('network');$('netSetup').hidden=false;$('netLobby').hidden=true;$('netStatus').textContent='地图版本不一致，请从新版游戏服务地址进入。';return}const previous=this.state;this.state=s;airdrops=s.airdrops||[];this.seq=Math.max(this.seq,s.self.seq||0);
  if((s.status==='playing'||s.status==='countdown')&&(!this.active||this.round!==s.round)){
   reset({network:true,mapId:s.mapId});this.active=true;this.round=s.round;this.menu=false;this.remote.clear();this.priorAmmo=null;this.target=null;this.seq=Math.max(0,s.self.seq||0);this.netClock=0;$('overlay').classList.add('hidden');$('netSetup').hidden=true;$('netLobby').hidden=false;clearInput();
  }
  if(this.active){FieldOps.sync(s);const self=s.self,teleport=!this.target||distanceForNet(player,self)>140||(player.hp<=0)!==(self.hp<=0);this.target={x:self.x,y:self.y};if(teleport){player.x=self.x;player.y=self.y;camera.x=player.x;camera.y=player.y}
   if(player.hp>self.hp){damageFlash=.25;sound('hit',.3)}if(this.priorAmmo!==null&&self.weapon===player.weapon&&self.ammo<this.priorAmmo){sound(self.weapon,self.mod==='suppressor'?.45:1);shake=1.2}this.priorAmmo=self.ammo;
   Object.assign(player,{...TZClasses.state(self,s.time),hp:self.hp,maxHp:self.maxHp||100,weapon:self.weapon,ammo:self.ammo,reserve:self.reserve,reload:self.reload,flash:self.flash,shieldUntil:self.shieldUntil,revealUntil:self.revealUntil,downed:self.downed,team:self.team,mod:self.mod,modStock:self.modStock});time=s.time;if(self.skillError&&self.skillError.at!==this.lastSkillError){this.lastSkillError=self.skillError.at;toast(self.skillError.text)}
   inventory.primary=self.primary?{type:self.primary}:null;const present=new Set();for(const peer of s.peers){present.add(peer.id);let a=this.remote.get(peer.id);if(!a){a={...peer,path:[],radius:16,recoil:0,hurt:0,elite:false,visible:true};this.remote.set(peer.id,a)}a.targetX=peer.x;a.targetY=peer.y;Object.assign(a,{...TZClasses.state(peer,s.time),angle:peer.angle,hp:peer.hp,maxHp:peer.maxHp||100,npc:peer.npc,weapon:peer.weapon,flash:peer.flash,revealUntil:peer.revealUntil,moving:peer.moving,shieldUntil:peer.shieldUntil,ally:peer.ally,team:peer.team,downed:peer.downed,mod:peer.mod})}for(const key of this.remote.keys())if(!present.has(key))this.remote.delete(key);enemies=[...this.remote.values()];
   bullets=s.bullets.map(b=>({...b,color:W[b.weapon].color,travelled:30}));crates=s.loot.filter(l=>l.type==='weapon').map(l=>({...l,type:l.weapon,phase:0}));this.containers=s.loot.filter(l=>l.type==='container').map(l=>({...l,progress:l.id===self.searchId?self.searchProgress:0}));
   miniAt=-1;DeathView.sync(s);
   if(s.status==='finished'){this.active=false;running=false;paused=false;this.menu=false;document.body.classList.remove('playing');$('overlay').classList.remove('hidden');$('overlay').dataset.screen='network';$('netBanner').textContent='';$('respawnNotice').textContent='';clearInput();sound('success',.5);if(DeathView.active)$('overlay').classList.add('hidden')}
  }
  if(s.status==='lobby'||s.status==='finished'||this.menu)this.lobby();
  RoomUI.sync(s,previous);if(previous?.status!==s.status)clearInput();
 },
 lobby(){const s=this.state;if(!s)return;RoomUI.lobby(s);$('netDeathSummary').textContent=s.self.death?'上次阵亡 · '+DeathView.text(s.self.death):'';ClassUI.lobby(s);this.inviteHint();$('netSetup').hidden=true;$('netLobby').hidden=false;$('roomLabel').textContent=s.code;const roster=$('netRoster');roster.innerHTML='';
  for(const p of s.roster){const row=document.createElement('div');row.className='netPlayer';const name=document.createElement('span'),info=document.createElement('span');name.textContent=(s.mode==='teams'?(p.team===0?'[青队] ':'[橙队] '):'')+p.name+' · '+(TZClasses.ROLES[p.classId]?.name||'先锋')+(p.id===s.owner?' · 房主':'')+(p.id===this.id?' · 你':'');info.textContent=s.status==='finished'?`${p.kills} 击杀 / ${p.deaths} 死亡 · ${p.objectivePoints||0} 目标分`:!p.connected?'重连中':p.ready?'已准备':'未准备';row.append(name,info);roster.appendChild(row)}
  const battle=s.status==='playing'||s.status==='countdown';$('netReady').hidden=battle;$('netStart').hidden=battle||s.owner!==this.id;$('netReturn').hidden=!battle;const me=s.roster.find(p=>p.id===this.id);$('netReady').textContent=me?.ready?'取消准备':'准备';$('netStart').disabled=s.roster.length<(s.mode==='teams'?4:2)||s.roster.some(p=>!p.ready||!p.connected);$('netTeam').hidden=s.mode!=='teams'||battle;$('netTeam').textContent='切换到'+(me?.team===0?'橙队':'青队');
  $('netStatus').textContent=s.status==='finished'?`对局结束 · ${s.winners.join(' / ')} 获胜。准备后可再来一局。`:battle?'联机不会暂停，菜单打开时角色仍可能受到攻击。':`等待准备 · ${s.roster.length} / 4 人 · ${MAPS[s.mapId].name}`;
 },
 controls(){if(!this.active||this.menu||document.hidden||width<=height||this.state?.status!=='playing'||player.hp<=0||this.socket?.readyState!==1||performance.now()-this.lastPacket>1500)return {x:0,y:0,angle:player?.angle||0,fire:false};
  let x=sticks.move.x+(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),y=sticks.move.y+(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0),n=Math.hypot(x,y);if(n<.12)x=y=0;else if(n>1){x/=n;y/=n}
  const aim=Math.hypot(sticks.aim.x,sticks.aim.y);let angle=player.angle;if(aim>.14)angle=Math.atan2(sticks.aim.y,sticks.aim.x);else if(mouse.active){const wx=(mouse.x-width/2)/camera.zoom+camera.x,wy=(mouse.y-height/2)/camera.zoom+camera.y;angle=Math.atan2(wy-player.y,wx-player.x)}
  return {x,y,angle,fire:mouse.down||aim>.35};
 },
 update(dt){if(!this.active)return;DeathView.tick(dt);if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0}hitTime=Math.max(0,hitTime-dt);killConfirm=Math.max(0,killConfirm-dt);const input=this.controls();player.angle=input.angle;player.moving=Math.hypot(input.x,input.y);const C=TZWorld.CONFIG;const pace=(this.state?.ops?.objective?.yours?.88:1)*TZClasses.speed(player,time);worldGeometry.move(player,input.x*C.speed*pace,input.y*C.speed*pace,dt);
  if(this.target&&performance.now()-this.lastPacket<500){const lead=Math.min(.12,this.rtt/2000+(performance.now()-this.lastPacket)/1000),tx=this.target.x+input.x*C.speed*pace*lead,ty=this.target.y+input.y*C.speed*pace*lead;if(worldGeometry.stand(tx,ty))worldGeometry.move(player,(tx-player.x)*12,(ty-player.y)*12,dt)}
  for(let i=damageDirections.length-1;i>=0;i--){damageDirections[i].life-=dt;if(damageDirections[i].life<=0)damageDirections.splice(i,1)}
  for(const a of enemies){a.x+=(a.targetX-a.x)*Math.min(1,dt*18);a.y+=(a.targetY-a.y)*Math.min(1,dt*18)}autoAimTarget=null;
  camera.x+=(player.x+Math.cos(player.angle)*35-camera.x)*Math.min(1,dt*9);camera.y+=(player.y+Math.sin(player.angle)*35-camera.y)*Math.min(1,dt*9);camera.zoom+=(baseZoom-camera.zoom)*Math.min(1,dt*8);damageFlash=Math.max(0,damageFlash-dt);shake=Math.max(0,shake-dt*15);hudTimer-=dt;if(hudTimer<=0){hudTimer=.1;this.hud()}
 },
 hud(){if(!this.state||!player)return;Art.rarityHUD();const s=this.state,me=s.roster.find(p=>p.id===this.id);$('weaponName').textContent=W[player.weapon].label;$('ammo').textContent=player.ammo+' / '+player.reserve;$('weaponStatus').textContent=player.reload>0?'换弹中 '+player.reload.toFixed(1)+'s':'手动瞄准'+(player.weapon==='AWP'?' · 5 发弹道狙击':'');$('enemyCount').textContent=(s.mode==='teams'?`青队 ${s.teamScores[0]} : ${s.teamScores[1]} 橙队 / ${s.settings?.scoreLimit||15} ${s.settings?.victory==='kills'?'人头':'分'}`:`${(me?.kills||0)+(s.settings?.victory==='kills'?0:me?.objectivePoints||0)} / ${s.settings?.scoreLimit||7} ${s.settings?.victory==='kills'?'人头':'分'}`)+' · '+clockText(Math.max(0,(s.settings?.matchSeconds||TZWorld.CONFIG.matchSeconds)-s.elapsed));
  $('switchWeapon').disabled=!s.self.primary;$('switchWeapon').textContent=s.self.primary?'切换 '+(player.weapon==='USP'?W[s.self.primary].label:'USP'):'未拾主武器';$('reload').disabled=W[player.weapon].limited;$('reload').textContent=W[player.weapon].limited?'限定弹药':player.reload>0?'换弹中':'换弹';$('shieldBuff').textContent=s.self.shieldUntil>s.time?'出生保护':'';$('ammoBuff').textContent='';$('zoneLabel').textContent=activeMap.name+' · '+(me?.score||0)+' ◈';
  const nearby=s.loot.filter(l=>dist(l,player)<62&&los(player,l)).sort((a,b)=>dist(a,player)-dist(b,player))[0];$('pickupWeapon').style.display='none';$('searchButton').style.display=nearby?'block':'none';$('searchButton').textContent=s.self.searchId?'搜索中 '+Math.round(s.self.searchProgress/(s.self.searchDuration||TZWorld.CONFIG.searchSeconds)*100)+'%':nearby?.type==='weapon'?'拾取 '+W[nearby.weapon].label+' [E]':nearby?'搜索 '+nearby.name+' [E]':'';
  $('netBanner').textContent=this.socket?.readyState!==1||performance.now()-this.lastPacket>1500?'连接中断 · 正在重连':`房间 ${s.code} · ${this.rtt} ms · 手动瞄准`;
  $('respawnNotice').textContent=s.status==='countdown'?Math.max(1,Math.ceil(s.countdown))+' · 准备战斗':player.downed?(s.self.downedBy?'被 '+s.self.downedBy.killerName+' 用 '+(W[s.self.downedBy.weapon]?.label||'未知武器')+' 击倒 · ':'倒地 · ')+Math.max(0,Math.ceil(s.self.bleedUntil-s.time))+' 秒内等待队友救援':player.hp<=0?'阵亡 · '+Math.max(1,Math.ceil(s.self.respawnAt-s.time))+' 秒后复活':'';
  $('netFeed').textContent=s.feed.map(f=>`${f.killer} › ${f.victim}`).join('\n');FieldOps.hud();ClassUI.hud();if(typeof ControlUI!=='undefined')ControlUI.sync();
 },
 pause(){if(!this.active)return;this.menu=true;clearInput();$('overlay').dataset.screen='network';$('overlay').classList.remove('hidden');document.body.classList.remove('playing');this.send({type:'input',seq:++this.seq,x:0,y:0,angle:player.angle,fire:false});this.lobby()},
 returnToBattle(){if(!this.active)return;this.menu=false;clearInput();$('overlay').classList.add('hidden');document.body.classList.add('playing')},
 leave(){DeathView.reset();RoomUI.reset();this.intentional=true;this.send({type:'leave'});this.socket?.close();this.socket=null;this.active=false;this.menu=false;this.state=null;this.id=this.token=this.code=null;this.round=0;this.remote.clear();this.target=null;this.containers=[];gameMode='solo';setModeUI();running=false;paused=false;clearInput();document.body.classList.remove('playing');$('netBanner').textContent=$('netFeed').textContent=$('respawnNotice').textContent='';$('searchButton').style.display='none';try{sessionStorage.removeItem('tactical-room')}catch(_){}},
 async invite(){if(!this.code)return;if(this.inviteHint()){$('netShareText').hidden=true;$('netShareText').value='';$('netStatus').textContent='未复制：localhost 只对本机有效，请用局域网地址打开后邀请。';return}const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('room',this.code);const text=url.href;try{await navigator.clipboard.writeText(text);$('netStatus').textContent='邀请链接已复制，发给朋友即可'}catch{$('netShareText').hidden=false;$('netShareText').value=text;$('netShareText').select();$('netStatus').textContent='请复制下方邀请链接'}},
};
function distanceForNet(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
$('homeMultiplayer').addEventListener('click',()=>TZNet.open());$('netCreate').addEventListener('click',()=>{unlock();TZNet.connect('create')});$('netJoin').addEventListener('click',()=>{if(!/^\d{6}$/.test($('netCode').value.trim())){$('netStatus').textContent='请输入朋友的六位房间码';return}unlock();TZNet.connect('join')});
$('netTeam').addEventListener('click',()=>TZNet.send({type:'team',team:TZNet.state?.roster.find(p=>p.id===TZNet.id)?.team===0?1:0}));
$('netReady').addEventListener('click',()=>TZNet.send({type:'ready',ready:!TZNet.state?.roster.find(p=>p.id===TZNet.id)?.ready}));$('netStart').addEventListener('click',()=>{unlock();TZNet.send({type:'start'});preferLandscape()});$('netLeave').addEventListener('click',()=>{TZNet.leave();showScreen('home')});$('netBack').addEventListener('click',()=>{TZNet.leave();showScreen('home')});$('netReturn').addEventListener('click',()=>TZNet.returnToBattle());$('netInvite').addEventListener('click',()=>TZNet.invite());
setInterval(()=>{if(TZNet.active&&TZNet.socket?.readyState===1)TZNet.send({type:'input',seq:++TZNet.seq,...TZNet.controls()})},1000/30);
setInterval(()=>{if(TZNet.socket?.readyState===1)TZNet.send({type:'ping',at:performance.now()})},2000);
addEventListener('pagehide',()=>{if(TZNet.active)TZNet.send({type:'input',seq:++TZNet.seq,x:0,y:0,angle:player.angle,fire:false})});
try{const room=new URL(location.href).searchParams.get('room');if(/^\d{6}$/.test(room||'')){$('netCode').value=room;TZNet.open()}else{const saved=JSON.parse(sessionStorage.getItem('tactical-room')||'null');if(saved?.code&&saved?.token){TZNet.available=true;showScreen('network');TZNet.code=saved.code;TZNet.token=saved.token;TZNet.connectSocket({type:'resume',...saved})}}}catch(_){}

